n\": null, \"id\": 0, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [694, 83, 835, 161], \"page_id\": 7}], \"content\": null, \"description\": null, \"id\": 1, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [187, 221, 1339, 516], \"page_id\": 7}], \"content\": \"TREASURY BULLETIN\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [687, 588, 799, 666], \"page_id\": 7}], \"content\": null, \"description\": null, \"id\": 3, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [477, 997, 911, 1062], \"page_id\": 7}], \"content\": \"JANUARY - 1950\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [192, 917, 353, 1116], \"page_id\": 7}], \"content\": null, \"description\": null, \"id\": 5, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [178, 1641, 1339, 1703], \"page_id\": 7}], \"content\": \"UNITED STATES TREASURY DEPARTMENT\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [853, 1701, 1332, 1741], \"page_id\": 7}], \"content\": \"OFFICE OF THE SECRETARY\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1192, 1180, 1389, 1221], \"page_id\": 7}], \"content\": \"LIBRARY\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1199, 1221, 1384, 1256], \"page_id\": 7}], \"content\": \"ROOM 5030\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1183, 1290, 1393, 1330], \"page_id\": 7}], \"content\": \"JUN 2.1 1972\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1094, 1355, 1482, 1402], \"page_id\": 7}], \"content\": \"TREASURY DEPARTMENT\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [0, 0, 1520, 1996], \"page_id\": 8}], \"content\": null, \"description\": null, \"id\": 0, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [93, 51, 267, 92], \"page_id\": 9}], \"content\": \"January 1950\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [634, 320, 951, 351], \"page_id\": 9}], \"content\": \"Table of Contents\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [1201, 434, 1262, 458], \"page_id\": 9}], \"content\": \"Page\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [316, 469, 1262, 1390], \"page_id\": 9}], \"content\": \"Treasury financing operations A-1\\nSummary of Federal fiscal operations 1\\nBudget receipts and expenditures 2\\nTrust accounts, etc 8\\nTreasury cash income and outgo 12\\nGeneral Fund of the Treasury 15\\nDebt outstanding 16\\nStatutory debt limitation 20\\nDebt operations 21\\nUnited States savings bonds 26\\nTreasury savings notes 29\\nOwnership of Federal securities 30\\nTreasury survey of ownership of Federal securities 32\\nMarket quotations 36\\nYields of Treasury and corporate bonds 39\\nInternal revenue collections 41\\nMonetary statistics 45\\nCapital movements 49\\nCumulative table of contents 63\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [131, 818, 184, 970], \"page_id\": 9}], \"content\": \"bed bed is not is a\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [316, 1449, 1188, 1549], \"page_id\": 9}], \"content\": \"Note: In those tables where figures have been rounded to a specified unit, all calculations (including percentages) have been made from unrounded figures. Consequently the details may not add to the totals shown.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [77, 27, 252, 67], \"page_id\": 11}], \"content\": \"January 1950\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1437, 45, 1472, 69], \"page_id\": 11}], \"content\": \"A-1\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [509, 107, 1052, 141], \"page_id\": 11}], \"content\": \"Treasury Financing Operations\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [115, 264, 565, 300], \"page_id\": 11}], \"content\": \"January Certificate Maturity\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [114, 306, 748, 626], \"page_id\": 11}], \"content\": \"On December 19, 1949, in accordance with his statement of November 30, the Secretary of the Treasury announced the offering of a one-year 1-1/8 percent certificate of indebtedness, in exchange for the 1-1/4 percent certificates of indebtedness, Series A-1950, which matured January 1 in the amount of $5,695 million. Subscription books for the new certificates, Series A-1951, were opened on December 19 and were closed at the close of business on December 22.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [112, 659, 746, 820], \"page_id\": 11}], \"content\": \"Exchanges were made par for par and cash subscriptions were not received. The certificates were dated January 1, 1950, and bear interest from that date at the rate of 1-1/8 percent per annum, payable with the principal at maturity on January 1,\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [818, 277, 1451, 344], \"page_id\": 11}], \"content\": \"to $5,372 million, leaving $323 million to be paid in cash.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [818, 367, 1281, 427], \"page_id\": 11}], \"content\": \"Results of December 15, 1949, Offering of Treasury Notes\", \"description\": null, \"id\": 7, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [818, 438, 1449, 816], \"page_id\": 11}], \"content\": \"Subscriptions to the 1-3/8 percent Treasury notes, Series A-1954, dated December 15, 1949, amounted to $4,671 million. They were offered in exchange for the certificates of indebtedness which matured December 15, and for the three issues of Treasury bonds which had been called for redemption on December 15. The maturing and called issues totaled $4,694 million, so that $223 million remained to be paid in cash. Results for each issue and their ownership by the commercial banking system as of October 31, 1949, were as follows:\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [206, 849, 1360, 1270], \"page_id\": 11}], \"content\": \"<table><tr><th>Maturing issue</th><th>Outstanding</th><th>Exchanged</th><th>Turned in for cash</th><th>Owned by reporting commercial banks and by Federal Reserve Banks</th></tr><tr><td colspan=\\\"2\\\">(In millions)</td><td colspan=\\\"2\\\"></td><td>(Percent of outstanding)</td></tr><tr><td>2% Treasury bonds of 1949-51 (dated July 15, 1942)</td><td>$2,098</td><td>$2,025</td><td>$72</td><td>75</td></tr><tr><td>3-1/8% Treasury bonds of 1949-52 (dated December 15, 1934)</td><td>491</td><td>467</td><td>24</td><td>81</td></tr><tr><td>2-1/2% Treasury bonds of 1949-53 (dated December 15, 1936)</td><td>1,786</td><td>1,695</td><td>91</td><td>83</td></tr><tr><td>1-1/4% Certificates of indebtedness (dated December 15, 1948) Series H</td><td>519</td><td>484</td><td>35</td><td>59</td></tr><tr><td>Total</td><td>4,894</td><td>4,671</td><td>223</td><td>77</td></tr></table>\", \"description\": null, \"id\": 9, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [117, 1297, 750, 1386], \"page_id\": 11}], \"content\": \"1951. They were issued in bearer form only, in denominations of $1,000, $5,000, $10,000, $100,000, and $1,000,000.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [117, 1422, 750, 1643], \"page_id\": 11}], \"content\": \"Reports to the Treasury on the ownership of Government securities indicate that on October 31, 1949, about 51 percent of the maturing certificates were owned by reporting commercial banks and Federal Reserve Banks. The ownership figures for October 31 are the latest available for the holdings of commercial banks.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [180, 1679, 748, 1708], \"page_id\": 11}], \"content\": \"Subscriptions to the new certificates amounted\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [114, 1748, 745, 1815], \"page_id\": 11}], \"content\": \"Note: Details of Treasury market financing operations are shown in the tables on \\\"Offerings\\\" and \\\"Disposition\\\", respectively, of marketable issues of bonds, notes,\", \"description\": null, \"id\": 13, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [821, 1292, 1190, 1321], \"page_id\": 11}], \"content\": \"Treasury Bills Refunded\", \"description\": null, \"id\": 14, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [821, 1328, 1452, 1710], \"page_id\": 11}], \"content\": \"Treasury bills maturing in December were refunded in the full amount of $4.7 billion. The issue of December 29 was the sixteenth in succession which represented neither an increase over nor a decrease from the amount maturing. Each of the issues of December 1 and 8 was for $1,000 million, and the remaining three were for $900 million each. The average rates of discount on the five December offerings were 1.108 percent for the issue of December 1, 1.115 percent for the issue of December 8, 1.116 percent for the issue of December 15, and 1.087 percent for the issues of December 22 and 29.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [814, 1748, 1435, 1813], \"page_id\": 11}], \"content\": \"and certificates of indebtedness, and in the table \\\"Offerings of Treasury Bills\\\", in this issue of the \\\"Treasury Bulletin\\\".\", \"description\": null, \"id\": 16, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [1470, 63, 1489, 83], \"page_id\": 13}], \"content\": \"1\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [491, 113, 1085, 140], \"page_id\": 13}], \"content\": \"SUMMARY OF FEDERAL FISCAL OPERATIONS\", \